import { DEMO_COMMUNITIES, DEMO_FACILITIES, communityById } from './reference';

/**
 * FICTIONAL GEOGRAPHY. Every shape here is generated by this file from a fixed seed. It is not
 * based on, derived from or similar to any real boundary. The coordinates sit in an empty part
 * of the coordinate system on purpose and the map is drawn without a real-world base map, so
 * nothing on it can be mistaken for a real place. It is for demonstration only.
 */
export const GEOGRAPHY_LABEL = 'FICTIONAL DEMONSTRATION GEOGRAPHY — NOT A REAL PLACE';

export type Position = [number, number];

export interface PolygonGeometry {
  type: 'Polygon';
  coordinates: Position[][];
}
export interface LineGeometry {
  type: 'LineString';
  coordinates: Position[];
}
export interface PointGeometry {
  type: 'Point';
  coordinates: Position;
}
export interface Feature<G, P> {
  type: 'Feature';
  id?: string;
  geometry: G;
  properties: P;
}
export interface FeatureCollection<G, P> {
  type: 'FeatureCollection';
  features: Feature<G, P>[];
}

export interface CommunityShape {
  id: string;
  name: string;
  stateId: string;
  lgaId: string;
  wardId: string;
  synthetic: true;
}
export interface FacilityShape {
  id: string;
  name: string;
  lgaId: string;
  kind: string;
  synthetic: true;
}
export interface BoundaryShape {
  level: 'ward' | 'lga' | 'state';
  synthetic: true;
}

export interface DemoGeography {
  communities: FeatureCollection<PolygonGeometry, CommunityShape>;
  facilities: FeatureCollection<PointGeometry, FacilityShape>;
  wardBoundaries: FeatureCollection<LineGeometry, BoundaryShape>;
  lgaBoundaries: FeatureCollection<LineGeometry, BoundaryShape>;
  stateBoundaries: FeatureCollection<LineGeometry, BoundaryShape>;
  /** Centre of every community polygon. */
  centroids: Record<string, Position>;
  /** [west, south, east, north] */
  bounds: [number, number, number, number];
}

// Where each community sits on the fictional lattice of its state: [column, row].
const LAYOUT: Record<string, { state: 'a' | 's'; col: number; row: number }> = {
  'com-01': { state: 'a', col: 0, row: 0 },
  'com-02': { state: 'a', col: 1, row: 0 },
  'com-03': { state: 'a', col: 2, row: 0 },
  'com-04': { state: 'a', col: 0, row: 1 },
  'com-05': { state: 'a', col: 1, row: 1 },
  'com-06': { state: 'a', col: 2, row: 1 },
  'com-07': { state: 'a', col: 0, row: 2 },
  'com-08': { state: 'a', col: 1, row: 2 },
  'com-09': { state: 'a', col: 2, row: 2 },
  'com-10': { state: 's', col: 0, row: 0 },
  'com-11': { state: 's', col: 1, row: 0 },
  'com-12': { state: 's', col: 2, row: 0 },
  'com-13': { state: 's', col: 0, row: 1 },
  'com-14': { state: 's', col: 1, row: 1 },
  'com-15': { state: 's', col: 2, row: 1 },
};

const CELL = 0.05; // degrees; about 5.5 km at this latitude, but it is not a real place
const ORIGINS = { a: [0.1, 0.2], s: [0.31, 0.2] } as const; // [lon, lat of the top-left corner]

/** Deterministic hash to [0, 1) for a lattice vertex, so shared corners always agree. */
function jitter(state: string, i: number, j: number, axis: number): number {
  let h = 2166136261;
  for (const c of `${state}:${i}:${j}:${axis}`) {
    h ^= c.charCodeAt(0);
    h = Math.imul(h, 16777619) >>> 0;
  }
  h ^= h >>> 15;
  h = Math.imul(h, 2246822507) >>> 0;
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

function vertex(state: 'a' | 's', i: number, j: number): Position {
  const [lon0, lat0] = ORIGINS[state];
  const amp = CELL * 0.22;
  const x = lon0 + i * CELL + (jitter(state, i, j, 0) - 0.5) * 2 * amp;
  const y = lat0 - j * CELL + (jitter(state, i, j, 1) - 0.5) * 2 * amp;
  return [round(x), round(y)];
}

const round = (n: number) => Math.round(n * 1e6) / 1e6;

function cellRing(state: 'a' | 's', col: number, row: number): Position[] {
  const a = vertex(state, col, row);
  const b = vertex(state, col + 1, row);
  const c = vertex(state, col + 1, row + 1);
  const d = vertex(state, col, row + 1);
  return [a, b, c, d, a];
}

function centroid(ring: Position[]): Position {
  const pts = ring.slice(0, -1);
  const x = pts.reduce((s, p) => s + p[0], 0) / pts.length;
  const y = pts.reduce((s, p) => s + p[1], 0) / pts.length;
  return [round(x), round(y)];
}

type Level = 'wardId' | 'lgaId' | 'stateId';

function boundaryLines(level: Level): FeatureCollection<LineGeometry, BoundaryShape> {
  const at = new Map<string, string>(); // "state:col:row" -> group id
  for (const c of DEMO_COMMUNITIES) {
    const l = LAYOUT[c.id]!;
    at.set(`${l.state}:${l.col}:${l.row}`, c[level]);
  }
  const group = (s: string, col: number, row: number) => at.get(`${s}:${col}:${row}`) ?? null;
  const features: Feature<LineGeometry, BoundaryShape>[] = [];
  const shape: BoundaryShape = {
    level: level === 'wardId' ? 'ward' : level === 'lgaId' ? 'lga' : 'state',
    synthetic: true,
  };
  for (const state of ['a', 's'] as const) {
    const cols = 3;
    const rows = state === 'a' ? 3 : 2;
    for (let row = 0; row <= rows; row++) {
      for (let col = 0; col < cols; col++) {
        // horizontal edge between the cell above and the cell below
        if (group(state, col, row - 1) !== group(state, col, row)) {
          features.push({
            type: 'Feature',
            geometry: {
              type: 'LineString',
              coordinates: [vertex(state, col, row), vertex(state, col + 1, row)],
            },
            properties: shape,
          });
        }
      }
    }
    for (let col = 0; col <= cols; col++) {
      for (let row = 0; row < rows; row++) {
        if (group(state, col - 1, row) !== group(state, col, row)) {
          features.push({
            type: 'Feature',
            geometry: {
              type: 'LineString',
              coordinates: [vertex(state, col, row), vertex(state, col, row + 1)],
            },
            properties: shape,
          });
        }
      }
    }
  }
  return { type: 'FeatureCollection', features };
}

function build(): DemoGeography {
  const centroids: Record<string, Position> = {};
  const communities: DemoGeography['communities']['features'] = DEMO_COMMUNITIES.map((c) => {
    const l = LAYOUT[c.id]!;
    const ring = cellRing(l.state, l.col, l.row);
    centroids[c.id] = centroid(ring);
    return {
      type: 'Feature',
      id: c.id,
      geometry: { type: 'Polygon', coordinates: [ring] },
      properties: {
        id: c.id,
        name: c.name,
        stateId: c.stateId,
        lgaId: c.lgaId,
        wardId: c.wardId,
        synthetic: true,
      },
    };
  });

  const facilities: DemoGeography['facilities']['features'] = DEMO_FACILITIES.map((f) => {
    const home = centroids[f.communityId]!;
    // nudge off the centroid so a facility never sits exactly under a community marker
    return {
      type: 'Feature',
      id: f.id,
      geometry: {
        type: 'Point',
        coordinates: [round(home[0] + CELL * 0.18), round(home[1] - CELL * 0.18)],
      },
      properties: { id: f.id, name: f.name, lgaId: f.lgaId, kind: f.kind, synthetic: true },
    };
  });

  const all = communities.flatMap((c) => c.geometry.coordinates[0]!);
  const xs = all.map((p) => p[0]);
  const ys = all.map((p) => p[1]);
  return {
    communities: { type: 'FeatureCollection', features: communities },
    facilities: { type: 'FeatureCollection', features: facilities },
    wardBoundaries: boundaryLines('wardId'),
    lgaBoundaries: boundaryLines('lgaId'),
    stateBoundaries: boundaryLines('stateId'),
    centroids,
    bounds: [Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys)],
  };
}

export const DEMO_GEOGRAPHY: DemoGeography = build();

/** Community ids that sit on the fictional map, for consistency checks. */
export function mappedCommunityIds(): string[] {
  return Object.keys(LAYOUT).filter((id) => communityById(id));
}
